/* harmony default export */ __webpack_exports__["default"] = ({
  props: ['value', 'labelKey', 'itemList'],

  data() {
    return {
      inputValue: '',
      current: 0,
      open: false
    };
  },

  methods: {
    updateValue() {
      if (this.open === false) {
        this.open = true;
        this.current = 0;
      }

      if (this.inputValue === '') {
        this.$emit('input', {});
      }
    },

    enter() {
      this.suggestionClick(this.current);
    },

    up() {
      if (this.current > 0) {
        this.current--;
      }
    },

    down() {
      if (this.current < this.matches.length - 1) {
        this.current++;
      }
    },

    isActive(index) {
      return index === this.current;
    },

    suggestionClick(index) {
      const value = {
        id: this.matches[index].id,
        name: this.matches[index][this.labelKey]
      };
      this.$emit('input', value);
      this.open = false;
    }

  },
  computed: {
    matches() {
      this.current = 0;

      if (this.inputValue !== '') {
        return this.itemList.filter(item => item[this.labelKey].indexOf(this.inputValue) >= 0);
      }

      return [];
    },

    openSuggestion() {
      return this.matches.length !== 0 && this.open === true;
    }

  },

  mounted() {
    this.inputValue = this.value.name || '';
  },

  watch: {
    value(newVal) {
      if (newVal.name) {
        this.inputValue = newVal.name;
      } else {
        this.inputValue = '';
      }
    }

  }
});

